#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());
    queue<int> positions;
    for (int i = 0; i < n; i++) positions.push(i);
    vector<long long> res(n, 0);
    for (int i = 0; i < n; i++) {
        int pos = positions.front();
        positions.pop();
        res[pos] = a[i];
        if (!positions.empty()) {
            positions.push(positions.front());
            positions.pop();
        }
    }
    for (int i = 0; i < n; i++) cout << res[i] << (i + 1 < n ? " " : "\n");

    return 0;
}

