import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        Arrays.sort(a);
        Deque<Integer> positions = new ArrayDeque<>();
        for (int i = 0; i < n; i++) positions.addLast(i);
        long[] res = new long[(int) n];
        for (int i = 0; i < n; i++) {
            int pos = positions.pollFirst();
            res[pos] = a[i];
            if (!positions.isEmpty()) positions.addLast(positions.pollFirst());
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(res[i]).append(i + 1 < n ? " " : "\n");
        System.out.print(sb);
    }
}
